"""Local-filesystem storage.

Safety rules, all enforced here rather than trusted from callers:

* keys are generated by the application and must match ``KEY_PATTERN`` (a two-hex shard directory
  and a UUID file name with an allow-listed extension), so a key can never carry ``..``, an
  absolute path, a drive letter or a client-supplied file name;
* the resolved path must still be inside the storage root (defence against symlinks);
* writes go to a temporary file in the same directory and are moved into place with an atomic
  ``os.replace``;
* files are created with mode 0600 and directories with 0700.
"""

from __future__ import annotations

import contextlib
import os
import re
import tempfile
import uuid
from pathlib import Path

from app.integrations.file_storage.base import StorageError

ALLOWED_EXTENSIONS = ("jpg", "png", "webp")
KEY_PATTERN = re.compile(
    r"^[0-9a-f]{2}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(?:"
    + "|".join(ALLOWED_EXTENSIONS)
    + r")$"
)


def new_storage_key(extension: str) -> str:
    """A fresh, unguessable key. ``extension`` must be one of ``ALLOWED_EXTENSIONS``."""
    if extension not in ALLOWED_EXTENSIONS:
        raise ValueError(f"unsupported extension {extension!r}")
    name = uuid.uuid4()
    return f"{name.hex[:2]}/{name}.{extension}"


class LocalFileStorage:
    def __init__(self, root: Path) -> None:
        self._root = root.resolve()
        self._root.mkdir(parents=True, exist_ok=True, mode=0o700)

    def _path(self, key: str) -> Path:
        if not KEY_PATTERN.fullmatch(key):
            raise StorageError("invalid storage key")
        path = (self._root / key).resolve()
        if not path.is_relative_to(self._root):
            raise StorageError("invalid storage key")
        return path

    def save(self, key: str, content: bytes) -> None:
        path = self._path(key)
        try:
            path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
            fd, tmp_name = tempfile.mkstemp(dir=path.parent, prefix=".upload-")
            try:
                with os.fdopen(fd, "wb") as handle:
                    handle.write(content)
                    handle.flush()
                    os.fsync(handle.fileno())
                os.chmod(tmp_name, 0o600)
                os.replace(tmp_name, path)
            except BaseException:
                with contextlib.suppress(FileNotFoundError):
                    os.unlink(tmp_name)
                raise
        except OSError as exc:
            raise StorageError("could not write file") from exc

    def read(self, key: str) -> bytes:
        path = self._path(key)
        try:
            return path.read_bytes()
        except OSError as exc:
            raise StorageError("could not read file") from exc

    def delete(self, key: str) -> None:
        path = self._path(key)
        try:
            path.unlink(missing_ok=True)
        except OSError as exc:
            raise StorageError("could not delete file") from exc
